import { useEffect, useState } from "react";
import {
  LiveKitRoom,
  VideoConference,
  RoomAudioRenderer,
  ControlBar,
} from "@livekit/components-react";
import "@livekit/components-styles";

/**
 * Public page — no authentication required.
 * The LiveKit JWT in the query string is the only credential needed.
 *
 * Expected query params (generated by slack-livekit-bridge):
 *   ?token=<livekit-jwt>&room=<room-name>&wsUrl=<wss://...>
 */
export default function Join() {
  const [params, setParams] = useState<{
    token: string;
    room: string;
    wsUrl: string;
  } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    const token = sp.get("token");
    const room = sp.get("room");
    const wsUrl = sp.get("wsUrl");

    if (!token || !room || !wsUrl) {
      setError("Invalid call link. Missing required parameters.");
      return;
    }

    setParams({ token, room, wsUrl });
  }, []);

  if (error) {
    return (
      <div className="h-screen flex items-center justify-center bg-[var(--color-surface-container-lowest)]">
        <div className="text-center space-y-3">
          <p className="text-[var(--color-error)] font-body font-semibold">{error}</p>
          <p className="text-sm text-[var(--color-on-surface-variant)] font-body">
            Ask the call initiator to send you a fresh link.
          </p>
        </div>
      </div>
    );
  }

  if (!params) {
    return (
      <div className="h-screen flex items-center justify-center bg-[var(--color-surface-container-lowest)]">
        <div className="w-6 h-6 border-2 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="h-screen w-full">
      <LiveKitRoom
        serverUrl={params.wsUrl}
        token={params.token}
        connect={true}
        video={true}
        audio={true}
        onDisconnected={() => {
          window.close();
        }}
      >
        <VideoConference />
        <RoomAudioRenderer />
        <ControlBar />
      </LiveKitRoom>
    </div>
  );
}
